<script setup lang="ts">
/**
 * Monitor Live — V57 Basket Dashboard (20 pairs)
 * Polls REST API for pair candles, trades, profit, balance.
 * Grid layout: 5 columns, sorted by basket z-score.
 */
import { use } from 'echarts/core';
import { LineChart, CandlestickChart } from 'echarts/charts';
import { GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, MarkAreaComponent, DataZoomComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';
import VChart from 'vue-echarts';
import TradeSummary from '@/components/monitor/TradeSummary.vue';
import { coin, PAIRS, PAIR_COLORS } from '@/components/monitor/types';

use([CanvasRenderer, LineChart, CandlestickChart, GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, MarkAreaComponent, DataZoomComponent]);

// ── API ──
const API_BASE = window.location.origin;
const API_USER = 'freqtrader';
const API_PASS = 'freqtrader';
let jwtToken = '';

async function apiLogin() {
  const resp = await fetch(`${API_BASE}/api/v1/token/login`, {
    method: 'POST',
    headers: { 'Authorization': 'Basic ' + btoa(API_USER + ':' + API_PASS) },
  });
  if (!resp.ok) throw new Error('Login failed');
  const data = await resp.json();
  jwtToken = data.access_token;
}

async function apiGet(endpoint: string) {
  if (!jwtToken) await apiLogin();
  const resp = await fetch(`${API_BASE}${endpoint}`, {
    headers: { 'Authorization': `Bearer ${jwtToken}` },
  });
  if (resp.status === 401) {
    await apiLogin();
    const retry = await fetch(`${API_BASE}${endpoint}`, {
      headers: { 'Authorization': `Bearer ${jwtToken}` },
    });
    return retry.json();
  }
  return resp.json();
}

// ── State ──
const connected = ref(false);
const strategyName = ref('');
const strategyTimeframe = ref('');
const lastUpdate = ref('');
const sortBy = ref<'z' | 'name' | 'signal' | 'trade'>('z');

// ── Live Data ──
const pairData = reactive<Record<string, any>>({});
const zHistory = reactive<Record<string, { labels: string[]; basketZ: number[] }>>({});
const btcHistory = reactive<{ labels: string[]; ohlc: number[][]; close: number[] }>({ labels: [], ohlc: [], close: [] });
const equityHistory = reactive<{ labels: string[]; values: number[] }>({ labels: [], values: [] });
const MAX_HISTORY = 200;

// ── Trade Stats ──
const openTrades = ref<any[]>([]);
const closedTrades = ref<any[]>([]);
const profitData = reactive({ totalProfit: 0, totalProfitPct: 0, winRate: 0, wins: 0, losses: 0, balance: 1000 });

// ── Activity Log ──
const activityLog = reactive<{ time: string; msg: string; color: string }[]>([]);
const MAX_LOG = 100;
const expandLog = ref(false);

function addLog(msg: string, color = '#8b949e') {
  const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  activityLog.push({ time, msg, color });
  if (activityLog.length > MAX_LOG) activityLog.shift();
}

// ── Expand/Collapse ──
const expandBtc = ref(true);
const expandZChart = ref(true);
const expandGrid = ref(true);
const expandEntry = ref(true);
const expandExit = ref(true);
const expandEquity = ref(false);
const expandHistory = ref(false);

// ── Helpers ──
function zColor(z: number): string {
  if (z > 2) return '#f85149';
  if (z > 1) return '#ff9800';
  if (z < -2) return '#4caf50';
  if (z < -1) return '#64ffda';
  return '#aaa';
}

function heatColor(pct: number): string {
  const p = Math.max(0, Math.min(100, pct));
  if (p >= 100) return '#4caf50';
  if (p >= 75) return '#81c784';
  if (p >= 50) return '#ffd54f';
  if (p >= 25) return '#ff9800';
  return '#f85149';
}

function fmtPrice(p: number): string {
  if (!p) return '--';
  if (p >= 1000) return p.toLocaleString(undefined, { maximumFractionDigits: 2 });
  if (p >= 1) return p.toFixed(4);
  return p.toFixed(6);
}

function fmtDuration(mins: number): string {
  if (!mins) return '';
  if (mins >= 60) return `${Math.floor(mins / 60)}h${mins % 60}m`;
  return `${mins}m`;
}

function fmtDate(dateStr: string): string {
  if (!dateStr) return '-';
  const d = new Date(dateStr);
  return `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

// ── Fetch config ──
async function fetchConfig() {
  try {
    const cfg = await apiGet('/api/v1/show_config');
    strategyName.value = (cfg.bot_name || cfg.strategy || '').replace(/_/g, ' ');
    strategyTimeframe.value = cfg.timeframe || '5m';
    addLog(`Connected to ${cfg.strategy} (${cfg.timeframe}) — ${cfg.state}`, '#4caf50');
    connected.value = true;
  } catch (e: any) {
    addLog(`Config fetch failed: ${e.message}`, '#f85149');
  }
}

// ── Poll REST API ──
async function pollStatus() {
  try {
    const data = await apiGet('/api/v1/status');
    openTrades.value = data || [];
  } catch { /* */ }
}

async function pollProfit() {
  try {
    const p = await apiGet('/api/v1/profit');
    if (p) {
      const w = p.winning_trades || 0;
      const l = p.losing_trades || 0;
      profitData.totalProfit = p.profit_all_coin || 0;
      profitData.totalProfitPct = p.profit_all_percent || 0;
      profitData.wins = w;
      profitData.losses = l;
      profitData.winRate = (w + l) > 0 ? w / (w + l) * 100 : 0;
    }
  } catch { /* */ }
}

async function pollBalance() {
  try {
    const b = await apiGet('/api/v1/balance');
    if (b) {
      const total = b.total || 0;
      profitData.balance = total;
      const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      if (!equityHistory.labels.length || equityHistory.labels[equityHistory.labels.length - 1] !== time) {
        equityHistory.labels.push(time);
        equityHistory.values.push(total);
        if (equityHistory.labels.length > MAX_HISTORY) {
          equityHistory.labels.shift();
          equityHistory.values.shift();
        }
      }
    }
  } catch { /* */ }
}

async function pollTrades() {
  try {
    const data = await apiGet('/api/v1/trades?limit=50');
    closedTrades.value = (data?.trades || []).reverse();
  } catch { /* */ }
}

// ── Poll Pair Candles ──
async function pollCandles() {
  const tf = strategyTimeframe.value || '5m';

  for (const pair of PAIRS) {
    try {
      const resp = await apiGet(`/api/v1/pair_candles?pair=${encodeURIComponent(pair)}&timeframe=${tf}&limit=100`);
      if (!resp?.data || !resp?.columns) continue;
      const cols = resp.columns;
      const rows = resp.data;
      if (rows.length === 0) continue;

      const lastRow = rows[rows.length - 1];
      const getCol = (name: string) => {
        const idx = cols.indexOf(name);
        return idx >= 0 ? lastRow[idx] : null;
      };

      const basketZ = getCol('basket_z') || 0;
      const basketSpread = getCol('basket_spread') || 0;

      pairData[pair] = {
        price: getCol('close'),
        basket_z: basketZ,
        basket_spread: basketSpread,
        vol_ratio: getCol('vol_ratio') || 1,
        vol_ok: getCol('vol_ok') ?? 1,
        btc_mom: getCol('btc_mom') || 0,
        btc_atr_z: getCol('btc_atr_z') || 0,
        btc_pump: getCol('btc_pump') || false,
        btc_dump: getCol('btc_dump') || false,
        btc_high_vol: getCol('btc_high_vol') || false,
        coinName: coin(pair),
      };

      // Z history
      const dateIdx = cols.indexOf('date');
      const bzIdx = cols.indexOf('basket_z');
      zHistory[pair] = { labels: [], basketZ: [] };
      for (const row of rows) {
        const d = new Date(row[dateIdx]);
        zHistory[pair].labels.push(`${d.getUTCHours().toString().padStart(2, '0')}:${d.getUTCMinutes().toString().padStart(2, '0')}`);
        zHistory[pair].basketZ.push(bzIdx >= 0 ? row[bzIdx] || 0 : 0);
      }
    } catch { /* */ }
  }

  // BTC candle history
  try {
    const resp = await apiGet(`/api/v1/pair_candles?pair=${encodeURIComponent('BTC/USDC:USDC')}&timeframe=${tf}&limit=100`);
    if (resp?.data && resp?.columns) {
      const cols = resp.columns;
      const dateIdx = cols.indexOf('date');
      const openIdx = cols.indexOf('open');
      const highIdx = cols.indexOf('high');
      const lowIdx = cols.indexOf('low');
      const closeIdx = cols.indexOf('close');
      btcHistory.labels = [];
      btcHistory.ohlc = [];
      btcHistory.close = [];
      for (const row of resp.data) {
        const d = new Date(row[dateIdx]);
        btcHistory.labels.push(`${(d.getUTCMonth() + 1)}/${d.getUTCDate()} ${d.getUTCHours().toString().padStart(2, '0')}:${d.getUTCMinutes().toString().padStart(2, '0')}`);
        btcHistory.ohlc.push([row[openIdx], row[closeIdx], row[lowIdx], row[highIdx]]);
        btcHistory.close.push(row[closeIdx]);
      }
    }
  } catch { /* */ }

  lastUpdate.value = new Date().toLocaleTimeString();
  addLog(`Poll: ${Object.keys(pairData).length} pairs | ${openTrades.value.length} open`, '#666');
}

// ── Sorted Pairs ──
const sortedPairs = computed(() => {
  const arr = PAIRS.filter(p => pairData[p]).map(p => ({ pair: p, ...pairData[p] }));

  if (sortBy.value === 'name') arr.sort((a, b) => a.pair.localeCompare(b.pair));
  else if (sortBy.value === 'z') arr.sort((a, b) => a.basket_z - b.basket_z);
  else if (sortBy.value === 'signal') {
    arr.sort((a, b) => {
      const sa = getSignal(a);
      const sb = getSignal(b);
      const prio: Record<string, number> = { long: 0, short: 1, neutral: 2 };
      return (prio[sa] || 2) - (prio[sb] || 2);
    });
  } else if (sortBy.value === 'trade') {
    arr.sort((a, b) => {
      const aT = openTrades.value.some(t => t.pair === a.pair) ? 0 : 1;
      const bT = openTrades.value.some(t => t.pair === b.pair) ? 0 : 1;
      return aT - bT || a.basket_z - b.basket_z;
    });
  }
  return arr;
});

function getSignal(d: any): string {
  const btcMom = d.btc_mom || 0;
  const bz = d.basket_z || 0;
  if (btcMom > 0 && bz < -2 && !d.btc_dump && !d.btc_high_vol && d.vol_ok) return 'long';
  if (btcMom < -1 && bz > 2 && !d.btc_pump && !d.btc_high_vol && d.vol_ok) return 'short';
  return 'neutral';
}

function pairHasTrade(pair: string): boolean {
  return openTrades.value.some(t => t.pair === pair);
}

function pairTrade(pair: string): any | null {
  return openTrades.value.find(t => t.pair === pair) || null;
}

// ── BTC Info ──
const btcInfo = computed(() => {
  const d = pairData['BTC/USDC:USDC'];
  if (!d) return { mom: 0, atrZ: 0, pump: false, dump: false, highVol: false, price: 0, regime: 'RANGING', regimeColor: '#ffd54f' };
  const mom = d.btc_mom || 0;
  let regime = 'RANGING';
  let regimeColor = '#ffd54f';
  if (mom > 0) { regime = 'BULL'; regimeColor = '#4caf50'; }
  else if (mom < -1) { regime = 'BEAR'; regimeColor = '#f85149'; }
  return { mom, atrZ: d.btc_atr_z || 0, pump: d.btc_pump, dump: d.btc_dump, highVol: d.btc_high_vol, price: d.price || 0, regime, regimeColor };
});

// ── Z-Score Chart (all pairs basket_z) ──
const liveZChart = computed(() => {
  const firstPair = PAIRS.find(p => zHistory[p]?.labels?.length > 0);
  if (!firstPair) return null;
  const labels = zHistory[firstPair].labels;
  if (labels.length < 2) return null;

  // Top 10 pairs by absolute z (most interesting)
  const ranked = PAIRS
    .filter(p => zHistory[p])
    .map(p => ({ pair: p, absZ: Math.abs(pairData[p]?.basket_z || 0) }))
    .sort((a, b) => b.absZ - a.absZ)
    .slice(0, 10);

  const series = ranked.map(({ pair }) => ({
    name: coin(pair),
    type: 'line' as const,
    data: zHistory[pair]?.basketZ || [],
    lineStyle: { width: pairHasTrade(pair) ? 3 : 1.5, opacity: 1 },
    itemStyle: { color: PAIR_COLORS[pair] || '#aaa' },
    symbol: 'none',
  }));

  return {
    animation: false,
    grid: { top: 30, right: 50, bottom: 25, left: 45 },
    tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
    legend: {
      data: ranked.map(r => coin(r.pair)),
      textStyle: { color: '#666', fontFamily: 'monospace', fontSize: 10 },
      top: 0,
    },
    xAxis: {
      type: 'category', data: labels,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace', interval: Math.floor(labels.length / 6) },
      axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { show: false },
    },
    yAxis: {
      type: 'value',
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
      axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { lineStyle: { color: '#21262d' } },
    },
    series: [
      { name: 'Entry-', type: 'line', data: labels.map(() => -2), lineStyle: { width: 1, type: 'dashed', color: '#4caf50', opacity: 0.3 }, symbol: 'none',
        markArea: { silent: true, itemStyle: { color: 'rgba(76,175,80,0.04)' }, data: [[{ yAxis: -2 }, { yAxis: -10 }]] } },
      { name: 'Entry+', type: 'line', data: labels.map(() => 2), lineStyle: { width: 1, type: 'dashed', color: '#f85149', opacity: 0.3 }, symbol: 'none',
        markArea: { silent: true, itemStyle: { color: 'rgba(248,81,73,0.04)' }, data: [[{ yAxis: 2 }, { yAxis: 10 }]] } },
      { name: 'Zero', type: 'line', data: labels.map(() => 0), lineStyle: { width: 1, type: 'dotted', color: '#30363d' }, symbol: 'none' },
      ...series,
    ],
  };
});

// ── BTC Chart ──
const liveBtcChart = computed(() => {
  if (btcHistory.labels.length < 2) return null;
  return {
    animation: false,
    grid: { top: 10, right: 50, bottom: 25, left: 60 },
    tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
    xAxis: {
      type: 'category', data: btcHistory.labels,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace', interval: Math.floor(btcHistory.labels.length / 5) },
      axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { show: false },
    },
    yAxis: {
      type: 'value', scale: true,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
      axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { lineStyle: { color: '#21262d' } },
    },
    series: [{ type: 'candlestick', data: btcHistory.ohlc, itemStyle: { color: '#4caf50', color0: '#f85149', borderColor: '#4caf50', borderColor0: '#f85149' } }],
  };
});

// ── Equity Curve ──
const liveEquityChart = computed(() => {
  if (equityHistory.values.length < 2) return null;
  const initial = equityHistory.values[0] || 1000;
  const current = equityHistory.values[equityHistory.values.length - 1] || initial;
  const profit = current - initial;
  return {
    option: {
      animation: false,
      grid: { top: 10, right: 50, bottom: 25, left: 60 },
      tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
      xAxis: { type: 'category', data: equityHistory.labels, axisLabel: { color: '#484f58', fontSize: 9 }, axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { show: false } },
      yAxis: { type: 'value', scale: true, axisLabel: { color: '#484f58', fontSize: 9 }, axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { lineStyle: { color: '#21262d' } } },
      series: [{
        type: 'line', data: equityHistory.values, symbol: 'none',
        lineStyle: { width: 2, color: profit >= 0 ? '#4caf50' : '#f85149' },
        areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [{ offset: 0, color: profit >= 0 ? 'rgba(76,175,80,0.15)' : 'rgba(248,81,73,0.15)' }, { offset: 1, color: 'rgba(0,0,0,0)' }] } },
      }],
    },
    current, profit, profitPct: ((current / initial - 1) * 100).toFixed(1),
  };
});

// ── Trade History stats ──
const historyTotals = computed(() => {
  const trades = closedTrades.value.filter(t => !t.is_open);
  const total = trades.length;
  const wins = trades.filter(t => (t.profit_ratio || 0) >= 0).length;
  const profits = trades.map(t => (t.profit_ratio || 0) * 100);
  const totalProfit = profits.reduce((a, b) => a + b, 0).toFixed(2);
  const avgProfit = total > 0 ? (profits.reduce((a, b) => a + b, 0) / total).toFixed(2) : '0.00';
  const best = total > 0 ? Math.max(...profits).toFixed(2) : '0.00';
  const worst = total > 0 ? Math.min(...profits).toFixed(2) : '0.00';
  return { total, wins, losses: total - wins, totalProfit, avgProfit, best, worst };
});

// ── Polling ──
let pollTimer: number | null = null;

onMounted(async () => {
  await fetchConfig();
  await pollStatus();
  await pollProfit();
  await pollBalance();
  await pollTrades();
  await pollCandles();

  pollTimer = window.setInterval(async () => {
    await pollCandles();
    await pollStatus();
    await pollProfit();
    await pollBalance();
  }, 30000);

  window.setInterval(pollTrades, 60000);
});

onUnmounted(() => {
  if (pollTimer) clearInterval(pollTimer);
});
</script>

<template>
  <div class="flex flex-col gap-3 p-4 h-full overflow-y-auto">

    <!-- Header -->
    <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-3">
      <div class="flex items-center gap-3 flex-wrap">
        <span class="text-xl font-bold" style="color: #64ffda">V57 Basket Monitor</span>
        <span v-if="strategyName" class="px-2 py-1 rounded-sm text-base font-bold" style="background: #7c4dff20; color: #b388ff; border: 1px solid #7c4dff33">{{ strategyName }}</span>
        <span v-if="strategyTimeframe" class="px-2 py-1 rounded-sm text-base font-bold" style="background: #ff980020; color: #ff9800; border: 1px solid #ff980033">{{ strategyTimeframe }}</span>
        <span class="px-2 py-1 rounded-sm text-base font-bold"
          :style="{ background: connected ? '#23863620' : '#f8514920', color: connected ? '#4caf50' : '#f85149', border: `1px solid ${connected ? '#238636' : '#f85149'}` }">
          {{ connected ? 'LIVE' : 'CONNECTING...' }}
        </span>
        <span class="text-base text-muted-color">{{ Object.keys(pairData).length }}/20 pairs</span>
        <span class="text-base text-muted-color ms-auto">{{ lastUpdate }}</span>
      </div>
      <div class="flex items-center gap-3 mt-2 flex-wrap" style="font-family: monospace; font-size: 12px;">
        <span style="color: #ffd54f">Basket Z-Score</span>
        <span style="color: #666">|</span>
        <span style="color: #ff9800">Lev 6x</span>
        <span style="color: #666">|</span>
        <span style="color: #4caf50">Kalman filter</span>
        <span style="color: #666">|</span>
        <span style="color: #64ffda">Dynamic stake</span>
        <span style="color: #666">|</span>
        <span style="color: #b388ff">Max 4 trades</span>
        <span style="color: #666">|</span>
        <span style="color: #8b949e">20 pairs</span>
      </div>
    </div>

    <!-- Trade Summary -->
    <TradeSummary
      :open-count="openTrades.length"
      :wins="profitData.wins"
      :losses="profitData.losses"
      :win-pct="String(profitData.winRate.toFixed(1))"
      :equity-current="profitData.balance"
      :profit-pct="String(profitData.totalProfitPct.toFixed(1))"
      :profit-positive="profitData.totalProfit >= 0"
    />

    <!-- BTC Chart -->
    <div v-if="liveBtcChart" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandBtc = !expandBtc">
        <span style="color: #ffd54f; font-size: 14px">{{ expandBtc ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-base font-bold" style="color: #ffd54f">BTC/USDC</span>
        <span class="text-base font-bold ms-2" :style="{ color: btcInfo.regimeColor }">{{ btcInfo.regime }}</span>
        <span class="text-base text-muted-color ms-2">Mom: {{ btcInfo.mom.toFixed(1) }}% | ATR: {{ btcInfo.atrZ.toFixed(1) }}</span>
        <span v-if="btcInfo.pump" class="text-base" style="color: #ffd54f">PUMP</span>
        <span v-if="btcInfo.dump" class="text-base" style="color: #f85149">DUMP</span>
        <span v-if="btcInfo.highVol" class="text-base" style="color: #f85149">HIGH VOL</span>
        <span class="text-base text-muted-color ms-auto">${{ btcInfo.price ? btcInfo.price.toLocaleString() : '--' }}</span>
      </div>
      <div v-show="expandBtc" class="px-3 pb-3">
        <VChart :option="liveBtcChart" style="height: 180px" autoresize />
      </div>
    </div>

    <!-- Z-Score Chart (top 10 pairs) -->
    <div v-if="liveZChart" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandZChart = !expandZChart">
        <span style="color: #ffd54f; font-size: 14px">{{ expandZChart ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #ffd54f">Basket Z-Score</span>
        <span class="text-muted-color text-base ms-2">top 10 by |z|</span>
      </div>
      <div v-show="expandZChart" class="px-3 pb-3">
        <VChart :option="liveZChart" style="height: 250px" autoresize />
      </div>
    </div>

    <!-- Pair Grid (20 pairs, 5 cols) -->
    <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandGrid = !expandGrid">
        <span style="color: #64ffda; font-size: 14px">{{ expandGrid ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #64ffda">All Pairs</span>
        <span class="text-muted-color text-base ms-2">{{ Object.keys(pairData).length }} pairs</span>
        <div class="ms-auto flex gap-1">
          <button v-for="s in ['z', 'name', 'signal', 'trade'] as const" :key="s"
