            <span class="px-1.5 py-0.5 rounded-sm text-sm font-bold"
              :style="{
                background: getSignal(d) === 'long' ? '#23863620' : getSignal(d) === 'short' ? '#f8514920' : '#21262d',
                color: getSignal(d) === 'long' ? '#4caf50' : getSignal(d) === 'short' ? '#f85149' : '#555',
              }">{{ getSignal(d).toUpperCase() }}</span>
          </div>
          <div class="text-sm text-muted-color">${{ fmtPrice(d.price) }}</div>

