          <div class="mt-1 mb-1" style="height: 4px; border-radius: 2px; background: #21262d; position: relative; overflow: hidden">
            <div style="position: absolute; top: 0; height: 100%; border-radius: 2px; transition: all 0.3s"
              :style="{
                left: Math.min(50, ((Math.max(-4, Math.min(4, d.basket_z)) + 4) / 8) * 100) + '%',
                width: Math.abs(((Math.max(-4, Math.min(4, d.basket_z)) + 4) / 8) * 100 - 50) + '%',
