            <div class="text-center">
              <div style="color: #555; font-size: 9px">VOL</div>
              <div class="font-bold" :style="{ color: d.vol_ok ? '#aaa' : '#f85149' }">{{ d.vol_ratio?.toFixed(1) }}x</div>
            </div>
          </div>

