          <span class="font-bold" :style="{ color: PAIR_COLORS[t.pair] || '#e0e0e0' }">{{ coin(t.pair) }}</span>
          <span :style="{ color: t.is_short ? '#f85149' : '#4caf50' }">{{ t.is_short ? 'SHORT' : 'LONG' }}</span>
