    <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandHistory = !expandHistory">
        <span style="color: #58a6ff; font-size: 14px">{{ expandHistory ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #58a6ff">Trade History</span>
        <span class="text-base text-muted-color ms-auto">{{ historyTotals.total }} trades</span>
      </div>
      <div v-show="expandHistory" class="px-3 pb-3">
        <div class="flex gap-4 mb-3 p-2 rounded-sm" style="background: #0d1117; font-family: monospace; font-size: 13px;">
          <div><span class="text-muted-color">Total:</span> <b>{{ historyTotals.total }}</b></div>
          <div><span class="text-muted-color">W/L:</span> <span style="color:#4caf50">{{ historyTotals.wins }}</span> / <span style="color:#f85149">{{ historyTotals.losses }}</span></div>
          <div><span class="text-muted-color">P&L:</span> <b :style="{ color: Number(historyTotals.totalProfit) >= 0 ? '#4caf50' : '#f85149' }">{{ historyTotals.totalProfit }}%</b></div>
          <div><span class="text-muted-color">Avg:</span> <b>{{ historyTotals.avgProfit }}%</b></div>
          <div><span class="text-muted-color">Best:</span> <span style="color:#4caf50">+{{ historyTotals.best }}%</span></div>
          <div><span class="text-muted-color">Worst:</span> <span style="color:#f85149">{{ historyTotals.worst }}%</span></div>
        </div>
        <div style="max-height: 400px; overflow-y: auto;">
          <div v-for="(t, i) in closedTrades" :key="t.trade_id"
