            :style="{ background: (t.profit_ratio || 0) >= 0 ? '#23863608' : '#f8514908' }">
            <span class="text-muted-color" style="width: 25px">{{ closedTrades.length - i }}</span>
            <span class="font-bold" style="width: 65px">{{ coin(t.pair) }}</span>
            <span style="width: 50px" :style="{ color: t.is_short ? '#f85149' : '#4caf50' }">{{ t.is_short ? 'SHORT' : 'LONG' }}</span>
            <span class="font-bold" style="width: 65px" :style="{ color: (t.profit_ratio || 0) >= 0 ? '#4caf50' : '#f85149' }">{{ ((t.profit_ratio || 0) * 100).toFixed(2) }}%</span>
            <span style="width: 55px; color: #58a6ff">${{ (t.profit_abs || 0).toFixed(2) }}</span>
            <span class="text-muted-color" style="width: 50px">{{ t.trade_duration }}m</span>
            <span class="text-muted-color">{{ t.exit_reason }}</span>
          </div>
        </div>
      </div>
