    <div v-if="liveEquityChart" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandEquity = !expandEquity">
        <span style="color: #4caf50; font-size: 14px">{{ expandEquity ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #4caf50">Equity Curve</span>
        <span class="text-lg font-bold ms-auto" :style="{ color: liveEquityChart.profit >= 0 ? '#4caf50' : '#f85149' }">
          ${{ liveEquityChart.current.toFixed(1) }} ({{ liveEquityChart.profit >= 0 ? '+' : '' }}{{ liveEquityChart.profitPct }}%)
        </span>
      </div>
      <div v-show="expandEquity" class="px-3 pb-3">
        <VChart :option="liveEquityChart.option" style="height: 150px" autoresize />
      </div>
    </div>

    <!-- Activity Log -->
    <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandLog = !expandLog">
        <span style="color: #8b949e; font-size: 14px">{{ expandLog ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #8b949e">Activity Log</span>
